import binascii
from typing import Union

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadPortNumber

from .tcp import TcpPdu


class FACOM(TcpPdu):
    POWER_OFF_STATUS = "01020100A188"
    POWER_ON_STATUS = "010201016048"
    POWER_ON_CODE = {
        1: "01050000FF008C3A",
        2: "01050001FF00DDFA",
        3: "01050002FF002DFA",
        4: "01050003FF007C3A",
        5: "01050004FF00CDFB",
        6: "01050005FF009C3B",
        7: "01050006FF006C3B",
        8: "01050007FF003DFB",
    }
    POWER_OFF_CODE = {
        1: "010500000000CDCA",
        2: "0105000100009C0A",
        3: "0105000200006C0A",
        4: "0105000300003DCA",
        5: "0105000400008C0B",
        6: "010500050000DDCB",
        7: "0105000600002DCB",
        8: "0105000700007C0B",
    }
    CHECK_CODE = {
        1: "010200000001B9CA",
        2: "010200010001E80A",
        3: "010200020001180A",
        4: "01020003000149CA",
        5: "010200040001F80B",
        6: "010200050001A9CB",
        7: "01020006000159CB",
        8: "010200070001080B",
    }
    DEFAULT_PORT = 4001

    def __init__(
            self,
            host: str,
            timeout: Union[float, int] = 10,
            retry_timeout: Union[float, int] = 5,
            port: int = DEFAULT_PORT
    ) -> None:
        self._max_ports = 8
        port = int(port)
        super(FACOM, self).__init__(
            host=host, port=port, timeout=timeout, retry_timeout=retry_timeout
        )

    @property
    def _port_setting(self):
        return {
            DeviceStatus.OFF: self.POWER_OFF_STATUS,
            DeviceStatus.ON: self.POWER_ON_STATUS,
        }

    def _build_command(self, port, status):
        self._verify_port_number(port)
        code_for_status = {
            DeviceStatus.ON: self.POWER_ON_CODE[port],
            DeviceStatus.OFF: self.POWER_OFF_CODE[port],
            None: self.CHECK_CODE[port],
        }
        return binascii.a2b_hex(code_for_status[status])

    def _verify_port_number(self, port):
        if port not in range(1, self._max_ports + 1):
            exc_msg = f"Port number is invalid: {port}"
            raise BadPortNumber(exc_msg)

    def _parse_response(self, response):
        return binascii.b2a_hex(response.encode(self._encoding)).decode().upper()
